const story = $input.item.json;
const sectionsStatus = story.sections_status || {};

const allSections = [
  { key: "intro", label: "Intro", text: story.story_parts?.intro || "" },
  { key: "development", label: "Development", text: story.story_parts?.developpement || "" },
  { key: "conclusion", label: "Conclusion", text: story.story_parts?.conclusion || "" }
];

const sectionsToGenerate = allSections.filter(s => {
  const st = sectionsStatus[s.key]?.status;
  return st !== "approved" && st !== "waiting_for_review";
});

return {
  title: story.title || "",
  story_id: story._id || story.id,
  bible_id: story.story_id,
  idea_id: story.idea_id,
  platform: story.platform,
  language: story.language,
  full_story: story.full_text || "",
  sections: sectionsToGenerate,
  all_section_keys: allSections.map(s => s.key),
  sections_status: sectionsStatus
};

const storyData = $('Init Sections').item.json;
const bibleDoc = $input.item.json;
const bible = bibleDoc.bible || {};

// Build a stable visual-consistency anchor from the protagonist(s)
const mainCharacters = (bible.characters || [])
  .filter(c => c.role === "protagonist" || c.role === "main")
  .map(c => {
    const attrs = c.important_attributes && typeof c.important_attributes === 'object'
      ? Object.entries(c.important_attributes).map(([k, v]) => `${k}: ${v}`).join(', ')
      : '';
    return `${c.name} (${c.role}) — traits: ${(c.traits || []).join(', ')}${attrs ? '; ' + attrs : ''}`;
  });

const character_visual_anchor = mainCharacters.length > 0
  ? mainCharacters.join(' | ')
  : "No fixed character description available — infer appearance from story context.";

return {
  ...storyData,
  character_visual_anchor,
  retry_count: 0,
  validated_images: []
};

const data = $input.item.json;

const clean = (str) => (str || '')
  .replace(/\\/g, '')
  .replace(/"/g, "'")
  .replace(/\n/g, ' ')
  .replace(/\r/g, '')
  .trim();

const prompt =
  "You are a visual art director for a children's storybook (ages 3-9). " +
  "Based on this story section, write ONLY a short scene description (2-3 sentences max) " +
  "describing the action and setting — no character description needed. " +
  "Story title: " + clean(data.title) + ". " +
  "Scene type: " + data.current_section + " (" + (data.current_index + 1) + " of " + data.SECTIONS.length + "). " +
  "Composition style: " + (
    data.current_section === "intro" ? "wide establishing shot, calm and curious mood." :
    data.current_section === "development" ? "dynamic composition, movement implied, exciting mood." :
    "warm centered shot, happy and peaceful resolution."
  ) + ". " +
  "Section text: " + clean(data.section_text) + ". " +
  "Rules: child-friendly, colorful, safe, no violence, no adult content, warm colors. " +
  "Respond ONLY with valid JSON: " +
  "{\"scene_description\": \"action and setting only, 2-3 sentences\", " +
  "\"mood\": \"happy/adventurous/etc\", " +
  "\"main_elements\": [\"element1\", \"element2\"]}";

const fireworks_body = JSON.stringify({
  model: "accounts/fireworks/models/deepseek-v4-pro-0813",
  max_tokens: 900,
  messages: [{ role: "user", content: prompt }]
});

return { ...data, scene_prompt: prompt, fireworks_body };

const response = $input.item.json;
const promptData = $('Build Scene Prompt').item.json;

let rawText = "";
const finishReason = response.choices?.[0]?.finish_reason;

try {
  rawText = response.choices[0].message.content;
} catch (e) {
  return { parse_error: true, error_message: "No content in LLM response: " + e.message,
    story_id: promptData.story_id, current_section: promptData.current_section };
}

if (typeof rawText !== 'string' || rawText.trim() === '') {
  return { parse_error: true, error_message: "Empty scene response",
    story_id: promptData.story_id, current_section: promptData.current_section };
}

if (finishReason === 'length') {
  return { parse_error: true, error_message: "Scene response truncated (finish_reason=length)",
    story_id: promptData.story_id, current_section: promptData.current_section };
}

const cleanedText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

function tryFixCommonJsonErrors(text) {
  return text
    .replace(/\]\]/g, ']')
    .replace(/\}\}(\s*,\s*")/g, '}$1')
    .replace(/\\"\]/g, '"]')
    .replace(/,(\s*[\}\]])/g, '$1');
}

let scene;
try {
  scene = JSON.parse(cleanedText);
} catch (e1) {
  try {
    scene = JSON.parse(tryFixCommonJsonErrors(cleanedText));
  } catch (e2) {
    return { parse_error: true, error_message: "JSON parse failed: " + e2.message,
      raw_response: cleanedText, story_id: promptData.story_id, current_section: promptData.current_section };
  }
}

// Build the final image-generation prompt: scene description + character consistency anchor
const image_prompt =
  "Illustration for a children's storybook (ages 3-9), soft studio lighting, clean edges, " +
  "cinematic composition, high-quality colorful render. " +
  "Character appearance (must stay consistent across all illustrations): " + promptData.character_visual_anchor + ". " +
  "Scene: " + scene.scene_description + " " +
  "Mood: " + (scene.mood || "warm and friendly") + ". " +
  "Key elements to include: " + (scene.main_elements || []).join(", ") + ".";

const gemini_body = JSON.stringify({
  contents: [
    {
      parts: [
        { text: image_prompt }
      ]
    }
  ],
  generationConfig: {
    responseModalities: ["IMAGE"]
  }
});

return {
  parse_error: false,
  story_id: promptData.story_id,
  current_section: promptData.current_section,
  current_index: promptData.current_index,
  title: promptData.title,
  scene,
  image_prompt,
  gemini_body
};

const storyState = $('Init Story State').item.json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.storyMeta) staticData.storyMeta = {};
staticData.storyMeta[storyState.story_id] = {
  title: storyState.title,
  all_section_keys: storyState.all_section_keys,
  sections_status: storyState.sections_status || {}
};

return {
  story_id: storyState.story_id,
  idea_id: storyState.idea_id,
  platform: storyState.platform,
  language: storyState.language,
  title: storyState.title,
  full_story: storyState.full_story,
  sections: storyState.sections,
  all_section_keys: storyState.all_section_keys,
  character_visual_anchor: storyState.character_visual_anchor
};

const data = $input.item.json; // { story_id, title, images: [...] }
const WEBHOOK_URL = "http://YOUR_N8N_HOST:5678/webhook/illustration-review";
const images = (data.images || []).sort((a, b) => a.index - b.index);

const buildActionUrl = (action, img) =>
  WEBHOOK_URL +
  "?action=" + action +
  "&story_id=" + data.story_id +
  "&section=" + img.section +
  "&current_index=" + img.index +
  "&retry_count=0" +
  "&file_id=" + (img.file_id || "") +
  "&drive_link=" + encodeURIComponent(img.drive_url || "");

const imageBlocks = images.map(img => {
  const isActionable = img.status === "waiting_for_review";
  const badge = img.status === "approved"
    ? "<span style=\"color:#22c55e;font-weight:bold;\">✅ Already approved</span>"
    : "";

  const actions = isActionable
    ? "<a href=\"" + buildActionUrl("approve", img) + "\" style=\"display:inline-block;background:#22c55e;color:white;padding:10px 24px;border-radius:8px;text-decoration:none;font-weight:bold;margin-right:12px;\">✅ Approve</a>" +
      "<a href=\"" + buildActionUrl("reject", img) + "\" style=\"display:inline-block;background:#ef4444;color:white;padding:10px 24px;border-radius:8px;text-decoration:none;font-weight:bold;\">❌ Reject</a>"
    : badge;

  return (
    "<div style=\"padding: 20px; border-bottom: 1px solid #eee;\">" +
      "<h2 style=\"color: #764ba2; font-size: 15px; margin: 0 0 8px; text-transform: capitalize;\">🎬 " + img.section + " (" + (img.index + 1) + "/" + images.length + ")</h2>" +
      (img.scene_description ? "<p style=\"color: #666; font-size: 13px; margin: 0 0 12px;\">" + img.scene_description + "</p>" : "") +
      "<div style=\"text-align: center;\">" +
        "<a href='" + img.drive_url + "'>" +
          "<img src='" + img.drive_url + "' alt='Illustration " + img.section + "' style=\"max-width: 100%; border-radius: 10px; border: 1px solid #eee;\" />" +
        "</a>" +
        "<p style=\"margin: 12px 0 0;\">" + actions + "</p>" +
      "</div>" +
    "</div>"
  );
}).join("");

const email_body =
  "<div style=\"font-family: Arial, sans-serif; max-width: 650px; margin: auto; border: 1px solid #e0e0e0; border-radius: 12px; overflow: hidden;\">" +
    "<div style=\"background: linear-gradient(135deg, #667eea, #764ba2); padding: 24px; text-align: center;\">" +
      "<h1 style=\"color: white; margin: 0; font-size: 22px;\">🖼️ Illustration Review</h1>" +
      "<p style=\"color: #e0d7ff; margin: 6px 0 0;\">" + images.length + " illustration(s) — review required</p>" +
    "</div>" +
    "<div style=\"padding: 20px; background: #f9f9f9; border-bottom: 1px solid #eee;\">" +
      "<table style=\"width: 100%; border-collapse: collapse;\">" +
        "<tr><td style=\"padding: 6px 0; color: #888; width: 120px;\">📖 Story ID</td><td style=\"padding: 6px 0; font-weight: bold; color: #333;\">" + data.story_id + "</td></tr>" +
        "<tr><td style=\"padding: 6px 0; color: #888;\">📌 Title</td><td style=\"padding: 6px 0; font-weight: bold; color: #333;\">" + data.title + "</td></tr>" +
      "</table>" +
    "</div>" +
    imageBlocks +
    "<div style=\"padding: 12px; text-align: center; background: #f3f4f6; border-top: 1px solid #eee;\">" +
      "<p style=\"color: #aaa; font-size: 12px; margin: 0;\">Content Factory — Automated Review System</p>" +
    "</div>" +
  "</div>";

return {
  story_id: data.story_id,
  title: data.title,
  email_subject: "[Review] Illustrations — " + data.title,
  email_body
};

const data = $input.item.json;

return {
  story_id: data.story_id,
  //status: 'generating_images',
  section_keys: data.sections.map(s => s.key), // ex: ["intro","development","conclusion"]
  updated_at: new Date().toISOString()
};

const data = $input.item.json;

return data.sections.map((s, i) => ({
  json: {
    story_id: data.story_id,
    idea_id: data.idea_id,
    platform: data.platform,
    language: data.language,
    title: data.title,
    full_story: data.full_story,
    character_visual_anchor: data.character_visual_anchor,
    SECTIONS: data.sections.map(sec => sec.key), // fixes the sections/SECTIONS mismatch
    current_section: s.key,
    section_label: s.label,
    section_text: s.text,
    current_index: i
  }
}));

const driveFile = $input.item.json;
const context = $('Parse Visual Prompt').item.json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.images) staticData.images = {};
if (!staticData.images[context.story_id]) staticData.images[context.story_id] = [];

staticData.images[context.story_id].push({
  section: context.current_section,
  index: context.current_index,
  file_id: driveFile.id,
  drive_url: driveFile.webViewLink || driveFile.webContentLink,
  scene_description: context.scene?.scene_description || ""
});

return [{
  json: {
    story_id: context.story_id,
    section: context.current_section,
    section_status_update: {
      status: "waiting_for_review",
      file_id: driveFile.id,
      drive_link: driveFile.webViewLink || driveFile.webContentLink
    }
  }
}];

const staticData = $getWorkflowStaticData('global');
const storyIds = Object.keys(staticData.storyMeta || {});

const output = storyIds.map(story_id => {
  const meta = staticData.storyMeta[story_id];
  const newImages = staticData.images?.[story_id] || [];
  const previousStatus = meta.sections_status || {};

  const images = meta.all_section_keys.map((key, i) => {
    const newOne = newImages.find(img => img.section === key);
    if (newOne) {
      return {
        section: key, index: i,
        file_id: newOne.file_id, drive_url: newOne.drive_url,
        scene_description: newOne.scene_description,
        status: "waiting_for_review"
      };
    }
    const prev = previousStatus[key] || {};
    return {
      section: key, index: i,
      file_id: prev.file_id, drive_url: prev.drive_link,
      status: prev.status || "pending"
    };
  });

  return { story_id, title: meta.title, images };
});

staticData.storyMeta = {};
staticData.images = {};

return output.map(o => ({ json: o }));

const item = $input.item.json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.pendingSections) staticData.pendingSections = [];
staticData.pendingSections.push(item);

return item;

const staticData = $getWorkflowStaticData('global');
const flat = staticData.pendingSections || [];
staticData.pendingSections = [];

if (flat.length === 0) {
  return [];
}

return flat.map(s => ({ json: s }));
